import{f as t,c as r,o as a,a5 as o}from"./chunks/framework.BsEAYNxL.js";const f=JSON.parse('{"title":"AI 编年史 01：寒武纪大爆发的序章","description":"","frontmatter":{"title":"AI 编年史 01：寒武纪大爆发的序章","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Preface","AI History","Chronicle","Methodology"],"ai_role":"writer","reading_stats":{"count":1101,"minutes":3}},"headers":[],"relativePath":"ai-chronicles/01-preface.md","filePath":"ai-chronicles/01-preface.md","lastUpdated":null}'),n={name:"ai-chronicles/01-preface.md"};function i(s,e,l,c,p,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<blockquote><p><strong>“History doesn&#39;t repeat itself, but it often rhymes.” —— Mark Twain</strong></p></blockquote><h2 id="为什么需要-编年史" tabindex="-1">为什么需要“编年史”？ <a class="header-anchor" href="#为什么需要-编年史" aria-label="Permalink to &quot;为什么需要“编年史”？&quot;">​</a></h2><p>作为一名正在从传统互联网向 AI 领域转型的工程师，我时常感到焦虑。</p><p>每天都有新的论文发布（arXiv 上每天几百篇 AI 相关论文），每天都有新的模型刷新 SOTA，每天都有新的开源项目在 GitHub 上霸榜。这种信息的爆炸式增长，很容易让人迷失在细枝末节中，只见树木，不见森林。</p><p>在学习的过程中，我逐渐意识到：<strong>技术的发展从来都不是跳跃的，而是连续的。</strong> 每一个看似横空出世的“黑科技”，背后都有其演进的逻辑链条：</p><ul><li>它解决了上一代技术的什么痛点？</li><li>它受到了什么启发？</li><li>它为什么在这个时间点爆发？</li></ul><p>当我们以 <strong>“时间线 (Timeline)”</strong> 为轴，去梳理各个细分领域的发展历程时，很多复杂的概念瞬间变得清晰起来。理解了 RNN 的梯度消失，自然就懂了为什么要搞 Transformer 的自注意力机制；理解了 GAN 的训练不稳定，自然就懂了为什么要搞 Diffusion 的物理去噪过程。</p><p><strong>“AI 编年史”系列文章</strong>正是基于这种“以史为鉴”的学习方法。我们试图回答：<strong>Why now? What problem? What&#39;s next?</strong></p><h2 id="ai-发展的三个底层定律" tabindex="-1">AI 发展的三个底层定律 <a class="header-anchor" href="#ai-发展的三个底层定律" aria-label="Permalink to &quot;AI 发展的三个底层定律&quot;">​</a></h2><p>在正式开始之前，有三个底层规律贯穿了所有技术的发展：</p><h3 id="_1-压缩即智能-compression-is-intelligence" tabindex="-1">1. 压缩即智能 (Compression is Intelligence) <a class="header-anchor" href="#_1-压缩即智能-compression-is-intelligence" aria-label="Permalink to &quot;1. 压缩即智能 (Compression is Intelligence)&quot;">​</a></h3><p>OpenAI 的 Ilya Sutskever 曾言：“如果你能最有效地压缩关于世界的信息，你就必须理解世界。”</p><p><strong>预测下一个 Token，本质上就是对世界的极致压缩。</strong></p><p><strong><a href="https://arxiv.org/abs/2001.08361" target="_blank" rel="noreferrer">缩放定律 (Scaling Laws, 2020)</a></strong> 是实现这一目标的手段。模型性能与参数量、数据量、计算量呈对数线性关系。<strong>大力出奇迹</strong>。只要堆算力、堆数据，模型就能更高效地压缩世界，智能随之涌现。这是过去 5 年的主旋律。</p><h3 id="_2-苦涩的教训-the-bitter-lesson" tabindex="-1">2. 苦涩的教训 (The Bitter Lesson) <a class="header-anchor" href="#_2-苦涩的教训-the-bitter-lesson" aria-label="Permalink to &quot;2. 苦涩的教训 (The Bitter Lesson)&quot;">​</a></h3><p>Rich Sutton 在 2019 年提出的著名观点：<strong><a href="http://www.incompleteideas.net/IncIdeas/BitterLesson.html" target="_blank" rel="noreferrer">长期来看，利用计算力（通用方法）总是胜过利用人类先验知识（特定方法）。</a></strong></p><p>这不仅是技术的更迭，更像是一场<strong>降维打击</strong>。就像数码相机消灭柯达、智能手机消灭功能机一样。当一个维度的算力/通用性指数级增长时，它会无情地碾压那些在低维度精心雕琢的“技巧”。</p><ul><li>深蓝战胜卡斯帕罗夫，靠的不是国际象棋知识，而是搜索。</li><li>AlphaGo 战胜李世石，靠的不是围棋定式，而是自我博弈。</li><li>ChatGPT 战胜语言学家，靠的不是语法规则，而是预测下一个 Token。</li></ul><h3 id="_3-结构统一-unification" tabindex="-1">3. 结构统一 (Unification) <a class="header-anchor" href="#_3-结构统一-unification" aria-label="Permalink to &quot;3. 结构统一 (Unification)&quot;">​</a></h3><p>Transformer 取代了 RNN、CNN，实现了 NLP、CV、多模态的大一统。为什么？</p><p>这体现了 <strong>KISS (Keep It Simple, Stupid)</strong> 原则的终极奥义。越是简单的结构，越具有强大的<strong>可扩展性 (Scalability)</strong>。复杂的精心设计往往难以并行，难以扩张，难以集成更先进的思想。</p><p>而简单的结构（如 Attention）可以无脑堆叠，更容易匹配缩放原则。因为结构统一，所以更容易 Scaling。万物皆 Token，万物皆 Attention。</p><h2 id="本系列章节概览" tabindex="-1">本系列章节概览 <a class="header-anchor" href="#本系列章节概览" aria-label="Permalink to &quot;本系列章节概览&quot;">​</a></h2><p>我们将沿着时间线，逐一探索以下领域：</p><ol start="2"><li><strong><a href="./02-context">上下文 (Context) 的记忆战争</a></strong>：从 RNN 的金鱼记忆，到 RAG 的外挂硬盘，再到 Gemini 的百万级无限上下文。</li><li><strong><a href="./03-diffusion">扩散模型 (Diffusion) 的造梦之旅</a></strong>：从 GAN 的左右互搏，到 Diffusion 的物理去噪，再到 Sora 的世界模拟器。</li><li><strong><a href="./04-architecture">架构演进 (Architecture) 的王者之路</a></strong>：Transformer 如何一统江湖？MoE 如何解决大而不当？</li><li><strong><a href="./05-agentic">智能体 (Agent) 的进化图谱</a></strong>：从简单的 Prompt 工程，到 ReAct 模式，再到能够自我规划的 Autonomous Agent。</li><li><strong><a href="./06-multimodal">多模态 (Multimodal) 的感官觉醒</a></strong>：AI 如何学会看 (Vision)、听 (Audio) 和说 (Speech)，并最终融为一体。</li><li><strong><a href="./07-alignment">对齐 (Alignment) 的驯化之路</a></strong>：从 RLHF 的人类反馈，到 Constitutional AI 的自我约束，确保 AI 不会毁灭世界。</li><li><strong><a href="./08-reasoning">推理 (Reasoning) 的慢思考</a></strong>：从 CoT 的思维链，到 AlphaGeometry 的符号推理，再到 o1 的 System 2 思考。</li></ol><p>让我们带着这些视角，开始这段旅程。</p>',26)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
